  // while stunned. Its two Scale calls use the base design speed, without sticky.
  if (target.dead) {
    state.target = null;
    return null;
  }
  const movement = actorDirection(
    target.rotation,
    target.stunned || target.status.stun > 0 ? 0 : target.design.speed,
  );
